const babyBudgetEmbeddedBase64 = "";


function decodeBabyBudgetSource() {
  const binary = atob(babyBudgetEmbeddedBase64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return new TextDecoder().decode(bytes);
}

function renderBabyBudget() {
  return `
    <iframe
      id="babyBudgetFrame"
      class="bb-iframe"
      title="Baby Budget original functional flow"
    ></iframe>
  `;
}

function mountBabyBudget() {
  const frame = document.getElementById("babyBudgetFrame");
  if (frame && !frame.dataset.loaded) {
    frame.addEventListener("load", () => {
      frame.contentWindow.postMessage({ type: "bb-theme", colorMode: state.settings.colorMode }, "*");
    }, { once: true });
    frame.srcdoc = decodeBabyBudgetSource();
    frame.dataset.loaded = "true";
  }
}

function reloadBabyBudget() {
  const frame = document.getElementById("babyBudgetFrame");
  if (frame) {
    frame.dataset.loaded = "";
    frame.srcdoc = decodeBabyBudgetSource();
    frame.dataset.loaded = "true";
  }
}

function renderBabyBudgetAdmin() {
  return `
    <div class="admin-card">
      <p class="admin-card-title">Baby Budget Developer Notes</p>
      <p class="helper">
        This screen embeds the original functional Baby Budget prototype instead of a simplified recreation.
        The original flow controls its own step navigation, sliders, debt rows, lifestyle tier selectors,
        budget generation, reset behavior, review, and saved state.
      </p>
    </div>

    <div class="admin-card">
      <p class="admin-card-title">Original Step Sequence</p>
      <div class="helper">
        1. Baby Budget<br>
        2. Basics<br>
        3. Housing<br>
        4. Bills<br>
        5. Carried Debt<br>
        6. Debt Cost<br>
        7. Food<br>
        8. Lifestyle<br>
        9. Planning<br>
        10. Adjust<br>
        11. Review<br>
        12. Saved
      </div>
    </div>

    <div class="admin-card">
      <p class="admin-card-title">Integration Note</p>
      <p class="helper">
        The Baby Budget flow is isolated in an embedded frame so the original slider math and render logic remain intact.
        Persistent app tabs remain outside the embedded flow through the main Money Buddy shell.
      </p>
      <button class="button full" type="button" onclick="reloadBabyBudget()">Reload Baby Budget</button>
    </div>
  `;
}
